-- ENTORNO SINTETICO DE PRUEBA, NO MIGRACION NI RESPALDO DE PRODUCCION.
-- products reproduce el DDL exportado. Las tablas auxiliares son el contrato
-- mínimo de los cuerpos reales; no se afirma que sea todo su DDL de producción.
-- Las cuatro funciones de abajo se extrajeron literalmente del CSV revisado.
create role anon;
create role authenticated;
create role service_role;
create schema auth;
create table auth.users(id uuid primary key, email text);
create function auth.uid() returns uuid language sql as $$ select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $$;
create function auth.jwt() returns jsonb language sql as $$ select jsonb_build_object('email','operador@example.test') $$;
create table public.inventory_members(user_id uuid primary key);
create table public.categories(id bigint primary key, name text not null unique);
create table public.products(
 id bigint generated by default as identity primary key,
 sku text not null unique check(btrim(sku) <> ''),
 name text not null check(btrim(name) <> ''),
 category_id bigint not null references categories(id),
 brand text not null default '', model text not null default '', characteristics text not null default '',
 stock integer not null default 0 check(stock >= 0),
 price numeric not null check(price >= 0 and price <> 'NaN'::numeric),
 min_stock integer not null default 5 check(min_stock >= 0),
 source_status text not null default '', created_at timestamptz not null default now(),
 version bigint not null default 1, created_by_name text
);
create index products_category_id_idx on products(category_id);
create table public.inventory_movements(
 id bigint generated by default as identity primary key, request_id uuid not null unique,
 request_data jsonb not null, product_id bigint, product_name text, sku text, type text,
 stock_before integer, stock_after integer,
 quantity integer generated always as (stock_after-stock_before) stored,
 actor_id uuid, actor_email text, reason text, before_data jsonb, after_data jsonb,
 created_at timestamptz not null default now()
);
create table public.inventory_sales(
 id uuid primary key, product_id bigint not null, product_name text not null, sku text not null,
 quantity integer not null check(quantity>0), unit_price numeric(12,2) not null check(unit_price>=0),
 total numeric(22,2) generated always as (quantity*unit_price) stored,
 expected_version bigint not null, movement_id text not null unique, actor_id uuid not null,
 actor_email text not null, created_at timestamptz not null default now(), rpc_result jsonb not null
);
alter table products enable row level security;
alter table inventory_members enable row level security;
alter table inventory_movements enable row level security;
alter table inventory_sales enable row level security;
create policy inventory_members_read_self on inventory_members for select to authenticated using(user_id=(select auth.uid()));
create policy products_read_members on products for select to authenticated using(exists(select 1 from inventory_members m where m.user_id=(select auth.uid())));
create policy movements_read_members on inventory_movements for select to authenticated using(exists(select 1 from inventory_members m where m.user_id=(select auth.uid())));
create policy inventory_sales_read_members on inventory_sales for select to authenticated using(exists(select 1 from inventory_members m where m.user_id=auth.uid()));
grant usage on schema public, auth to authenticated, anon;
grant select on products, inventory_members, inventory_movements, categories to authenticated;
grant select(id,product_id,product_name,sku,quantity,unit_price,total,expected_version,movement_id,actor_id,actor_email,created_at) on inventory_sales to authenticated;
insert into auth.users values ('00000000-0000-4000-8000-000000000001','operador@example.test');
insert into inventory_members values ('00000000-0000-4000-8000-000000000001');
insert into categories values(1,'Periféricos');
CREATE OR REPLACE FUNCTION public.inventory_mutate(p_request_id uuid, p_action text, p_product_id bigint, p_expected_version bigint, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  actor uuid := auth.uid();
  actor_name text;
  registered_by text;
  before_product public.products%rowtype;
  after_product public.products%rowtype;
  saved public.inventory_movements%rowtype;

  request jsonb := jsonb_build_object(
    'action', p_action,
    'product_id', p_product_id,
    'version', p_expected_version,
    'data', p_data
  );

  movement_type text;
  movement_reason text;
  requested_stock numeric;
  requested_min numeric;
  requested_price numeric;
  category bigint;
  delta integer;

BEGIN
  IF actor IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.inventory_members
    WHERE user_id = actor
  ) THEN
    RAISE EXCEPTION 'INVENTORY_FORBIDDEN'
      USING errcode = '42501';
  END IF;

  IF p_request_id IS NULL
    OR p_action IS NULL
    OR p_action NOT IN ('add', 'edit', 'delete', 'adjust')
    OR p_data IS NULL
    OR jsonb_typeof(p_data) <> 'object'
  THEN
    RAISE EXCEPTION 'INVENTORY_INVALID_INPUT'
      USING errcode = '22023';
  END IF;

  -- Evita movimientos duplicados al reintentar.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(p_request_id::text, 0)
  );

  SELECT *
  INTO saved
  FROM public.inventory_movements
  WHERE request_id = p_request_id;

  IF FOUND THEN
    IF saved.actor_id IS DISTINCT FROM actor
      OR saved.request_data IS DISTINCT FROM request
    THEN
      RAISE EXCEPTION 'INVENTORY_REQUEST_CONFLICT'
        USING errcode = '22023';
    END IF;

    RETURN jsonb_build_object(
      'product', saved.after_data,
      'movement', to_jsonb(saved)
    );
  END IF;

  -- Conserva el usuario autenticado en el historial.
  SELECT coalesce(email, actor::text)
  INTO actor_name
  FROM auth.users
  WHERE id = actor;

  IF p_action <> 'add' THEN
    SELECT *
    INTO before_product
    FROM public.products
    WHERE id = p_product_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'INVENTORY_NOT_FOUND'
        USING errcode = 'P0002';
    END IF;

    IF p_action IN ('edit', 'delete')
      AND before_product.version
        IS DISTINCT FROM p_expected_version
    THEN
      RAISE EXCEPTION 'INVENTORY_STALE_VERSION'
        USING errcode = '40001';
    END IF;
  END IF;

  IF p_action IN ('add', 'edit') THEN
    IF nullif(btrim(p_data->>'name'), '') IS NULL
      OR nullif(btrim(p_data->>'sku'), '') IS NULL
      OR length(p_data->>'name') > 500
      OR length(p_data->>'sku') > 100
      OR coalesce(jsonb_typeof(p_data->'stock'), '') <> 'number'
      OR coalesce(jsonb_typeof(p_data->'min_stock'), '') <> 'number'
      OR coalesce(jsonb_typeof(p_data->'price'), '') <> 'number'
    THEN
      RAISE EXCEPTION 'INVENTORY_INVALID_INPUT'
        USING errcode = '22023';
    END IF;

    -- Nombre escrito en "Registrado por".
    IF p_data ? 'created_by_name' THEN
      IF coalesce(
          jsonb_typeof(p_data->'created_by_name'), ''
        ) <> 'string'
        OR nullif(
          btrim(p_data->>'created_by_name'), ''
        ) IS NULL
        OR length(
          btrim(p_data->>'created_by_name')
        ) > 120
      THEN
        RAISE EXCEPTION 'INVENTORY_INVALID_INPUT'
          USING errcode = '22023';
      END IF;

      registered_by := btrim(p_data->>'created_by_name');

    ELSIF p_action = 'edit' THEN
      -- Si un cliente anterior no envía el campo, conserva el nombre.
      registered_by := before_product.created_by_name;
    END IF;

    requested_stock := (p_data->>'stock')::numeric;
    requested_min := (p_data->>'min_stock')::numeric;
    requested_price := (p_data->>'price')::numeric;

    IF requested_stock < 0
      OR requested_stock > 2147483647
      OR trunc(requested_stock) <> requested_stock
      OR requested_min < 0
      OR requested_min > 2147483647
      OR trunc(requested_min) <> requested_min
      OR requested_price < 0
      OR requested_price >= 10000000000
      OR round(requested_price, 2) <> requested_price
    THEN
      RAISE EXCEPTION 'INVENTORY_INVALID_INPUT'
        USING errcode = '22023';
    END IF;

    SELECT id
    INTO category
    FROM public.categories
    WHERE name = p_data->>'category';

    IF NOT FOUND THEN
      RAISE EXCEPTION 'INVENTORY_INVALID_CATEGORY'
        USING errcode = '22023';
    END IF;

    IF p_action = 'add' THEN
      INSERT INTO public.products (
        sku,
        name,
        category_id,
        stock,
        price,
        min_stock,
        created_by_name
      )
      VALUES (
        btrim(p_data->>'sku'),
        btrim(p_data->>'name'),
        category,
        requested_stock,
        requested_price,
        requested_min,
        registered_by
      )
      RETURNING * INTO after_product;

      movement_type := 'Alta';
      movement_reason := 'Registro de producto';

    ELSE
      UPDATE public.products
      SET
        sku = btrim(p_data->>'sku'),
        name = btrim(p_data->>'name'),
        category_id = category,
        stock = requested_stock,
        price = requested_price,
        min_stock = requested_min,
        created_by_name = registered_by,
        version = version + 1
      WHERE id = p_product_id
      RETURNING * INTO after_product;

      movement_type := 'Ajuste';
      movement_reason := 'Edición de producto';
    END IF;

  ELSIF p_action = 'delete' THEN
    DELETE FROM public.products
    WHERE id = p_product_id;

    movement_type := 'Baja';
    movement_reason := 'Eliminación de producto';

  ELSE
    IF p_data->>'delta' NOT IN ('-1', '1')
      OR p_data->>'delta' IS NULL
    THEN
      RAISE EXCEPTION 'INVENTORY_INVALID_INPUT'
        USING errcode = '22023';
    END IF;

    delta := (p_data->>'delta')::integer;

    IF before_product.stock + delta < 0 THEN
      RAISE EXCEPTION 'INVENTORY_NEGATIVE_STOCK'
        USING errcode = '22023';
    END IF;

    UPDATE public.products
    SET
      stock = stock + delta,
      version = version + 1
    WHERE id = p_product_id
    RETURNING * INTO after_product;

    movement_type := CASE
      WHEN delta > 0 THEN 'Entrada'
      ELSE 'Salida'
    END;

    movement_reason := 'Cambio manual de existencias';
  END IF;

  INSERT INTO public.inventory_movements (
    request_id,
    request_data,
    product_id,
    product_name,
    sku,
    type,
    stock_before,
    stock_after,
    actor_id,
    actor_email,
    reason,
    before_data,
    after_data
  )
  VALUES (
    p_request_id,
    request,
    coalesce(after_product.id, before_product.id),
    coalesce(after_product.name, before_product.name),
    coalesce(after_product.sku, before_product.sku),
    movement_type,
    coalesce(before_product.stock, 0),
    coalesce(after_product.stock, 0),
    actor,
    actor_name,
    movement_reason,
    CASE
      WHEN p_action = 'add' THEN NULL
      ELSE to_jsonb(before_product)
    END,
    CASE
      WHEN p_action = 'delete' THEN NULL
      ELSE to_jsonb(after_product)
    END
  )
  RETURNING * INTO saved;

  RETURN jsonb_build_object(
    'product', saved.after_data,
    'movement', to_jsonb(saved)
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.inventory_register_sale(p_request_id uuid, p_product_id bigint, p_expected_version bigint, p_quantity integer, p_unit_price numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_user uuid := auth.uid();
  v_product public.products%rowtype;
  v_sale public.inventory_sales%rowtype;
  v_category text;
  v_result jsonb;
begin
  if v_user is null or not exists (select 1 from public.inventory_members where user_id = v_user)
    or public.inventory_write_enabled() is distinct from true then
    raise exception 'INVENTORY_FORBIDDEN';
  end if;
  if p_request_id is null or p_product_id is null or p_product_id <= 0
    or p_expected_version is null or p_expected_version <= 0
    or p_quantity is null or p_quantity <= 0 or p_unit_price is null
    or p_unit_price < 0 or p_unit_price >= 10000000000
    or p_unit_price::text in ('NaN', 'Infinity', '-Infinity')
    or p_unit_price <> round(p_unit_price, 2)
    or p_quantity::numeric * p_unit_price > 90071992547409.91 then
    raise exception 'INVENTORY_INVALID_INPUT';
  end if;

  -- Serializa reintentos del mismo ID, incluidos los de conexiones distintas.
  perform pg_advisory_xact_lock(hashtextextended(p_request_id::text, 0));
  select * into v_sale from public.inventory_sales where id = p_request_id;
  if found then
    if v_sale.actor_id <> v_user or v_sale.product_id <> p_product_id
      or v_sale.expected_version <> p_expected_version or v_sale.quantity <> p_quantity
      or v_sale.unit_price <> p_unit_price then
      raise exception 'INVENTORY_REQUEST_CONFLICT';
    end if;
    return v_sale.rpc_result || jsonb_build_object('sale', to_jsonb(v_sale) - 'rpc_result');
  end if;

  select * into v_product from public.products where id = p_product_id for update;
  if not found then raise exception 'INVENTORY_NOT_FOUND'; end if;
  if v_product.version <> p_expected_version then raise exception 'INVENTORY_STALE_VERSION'; end if;
  if p_quantity > v_product.stock then raise exception 'INVENTORY_NEGATIVE_STOCK'; end if;
  select name into v_category from public.categories where id = v_product.category_id;
  if v_category is null then raise exception 'INVENTORY_INVALID_CATEGORY'; end if;

  -- Reutiliza el contrato de edición existente. Precio y atributos no cambian.
  -- Stock, historial y venta se confirman en la MISMA transacción PostgreSQL.
  select public.inventory_mutate(
    p_request_id => p_request_id,
    p_action => 'edit',
    p_product_id => v_product.id,
    p_expected_version => v_product.version,
    p_data => jsonb_build_object('name', v_product.name, 'sku', v_product.sku,
      'category', v_category, 'stock', v_product.stock - p_quantity,
      'min_stock', v_product.min_stock, 'price', v_product.price)
  ) into v_result;

  -- Impide aceptar respuestas vacías o el replay de una operación de otro tipo.
  if v_result->'movement'->>'id' is null
    or (v_result->'product'->>'id')::bigint is distinct from p_product_id
    or (v_result->'product'->>'stock')::integer is distinct from v_product.stock - p_quantity
    or (v_result->'product'->>'version')::bigint is distinct from p_expected_version + 1 then
    raise exception 'INVENTORY_REQUEST_CONFLICT';
  end if;
  if not exists (select 1 from public.products where id = p_product_id
    and stock = v_product.stock - p_quantity and version = p_expected_version + 1) then
    raise exception 'INVENTORY_REQUEST_CONFLICT';
  end if;

  insert into public.inventory_sales (id, product_id, product_name, sku, quantity, unit_price,
    expected_version, movement_id, actor_id, actor_email, rpc_result)
  values (p_request_id, p_product_id, v_product.name, v_product.sku, p_quantity, p_unit_price,
    p_expected_version, v_result->'movement'->>'id', v_user, coalesce(auth.jwt()->>'email', ''), v_result)
  returning * into v_sale;
  return v_result || jsonb_build_object('sale', to_jsonb(v_sale) - 'rpc_result');
end;
$function$;

CREATE OR REPLACE FUNCTION public.inventory_sales_enabled()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select exists (select 1 from public.inventory_members where user_id = auth.uid());
$function$;

CREATE OR REPLACE FUNCTION public.inventory_write_enabled()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select exists (select 1 from public.inventory_members where user_id = (select auth.uid()));
$function$;
revoke all on function public.inventory_mutate(uuid,text,bigint,bigint,jsonb) from public, anon;
grant execute on function public.inventory_mutate(uuid,text,bigint,bigint,jsonb) to authenticated, service_role;
revoke all on function public.inventory_register_sale(uuid,bigint,bigint,integer,numeric) from public, anon;
grant execute on function public.inventory_register_sale(uuid,bigint,bigint,integer,numeric) to authenticated, service_role;
revoke all on function public.inventory_sales_enabled() from public, anon;
grant execute on function public.inventory_sales_enabled() to authenticated, service_role;
revoke all on function public.inventory_write_enabled() from public, anon;
grant execute on function public.inventory_write_enabled() to authenticated, service_role;

